<?php
declare(strict_types=1);
require dirname(__DIR__) . '/app/bootstrap.php';
$user = requireLogin();
require_once BASE_PATH . '/includes/rental-operations-common.php';
ro_require_permission('agreements.manage');
$pdo = Database::connection();
if (is_post()) {
    ro_post_guard();
    try {
        $id = RentalOperations::createAgreement($pdo, (int)($_POST['reservation_id'] ?? 0), isset($user['user_id']) ? (int)$user['user_id'] : null);
        ro_flash('success', 'Agreement created or already existed. Review the details and issue it when ready.');
        redirect('admin/agreement-view.php?id=' . $id);
    } catch (Throwable $e) { ro_flash('danger', $e->getMessage()); redirect('admin/agreements.php'); }
}
$pageTitle = 'Rental Agreements'; $currentPage = 'agreements';
$reservations = $pdo->query("SELECT r.reservation_id,r.reservation_code,r.pickup_datetime,r.return_datetime,r.daily_rate,r.estimated_amount,r.security_deposit,c.first_name,c.last_name,v.make,v.model,v.registration_no FROM reservations r JOIN customers c ON c.customer_id=r.customer_id JOIN vehicles v ON v.vehicle_id=r.vehicle_id LEFT JOIN rental_agreements a ON a.reservation_id=r.reservation_id WHERE r.status='confirmed' AND a.agreement_id IS NULL ORDER BY r.pickup_datetime ASC")->fetchAll(PDO::FETCH_ASSOC);
$agreements = $pdo->query('SELECT a.agreement_id,a.agreement_number,a.status,a.created_at,a.agreed_daily_rate,a.security_deposit,c.first_name,c.last_name,r.reservation_code,v.make,v.model,v.registration_no FROM rental_agreements a JOIN customers c ON c.customer_id=a.customer_id JOIN reservations r ON r.reservation_id=a.reservation_id JOIN vehicles v ON v.vehicle_id=a.vehicle_id ORDER BY a.agreement_id DESC LIMIT 100')->fetchAll(PDO::FETCH_ASSOC);
require BASE_PATH . '/includes/header.php'; require BASE_PATH . '/includes/rental-operations-nav.php';
?>
<div class="ro-shell"><section class="ro-page-heading"><div><span class="ro-kicker">CONTRACT MANAGEMENT</span><h1>Rental agreements</h1><p>Create a draft from a confirmed reservation, review its terms, then issue and mark it signed before opening a rental.</p></div><div class="ro-heading-symbol"><i class="bi bi-file-earmark-text"></i></div></section>
<section class="ro-panel mb-4"><div class="ro-panel-head"><div><span class="ro-kicker">READY TO PREPARE</span><h2>Confirmed reservations</h2></div><span class="ro-counter"><?= count($reservations) ?> ready</span></div>
<?php if (!$reservations): ?><div class="ro-empty"><div class="ro-empty-icon"><i class="bi bi-check2-circle"></i></div><strong>You're up to date</strong><p>There are no confirmed reservations waiting for an agreement.</p></div><?php else: ?><div class="table-responsive"><table class="table ro-table align-middle"><thead><tr><th>Reservation</th><th>Customer</th><th>Vehicle</th><th>Pickup / return</th><th>Estimated amount</th><th></th></tr></thead><tbody><?php foreach ($reservations as $r): ?><tr><td><strong><?= e($r['reservation_code']) ?></strong><small class="d-block text-secondary">#<?= (int)$r['reservation_id'] ?></small></td><td><?= e($r['first_name'].' '.$r['last_name']) ?></td><td><?= e($r['make'].' '.$r['model']) ?><small class="d-block text-secondary"><?= e($r['registration_no']) ?></small></td><td><?= e(ro_date($r['pickup_datetime'])) ?><small class="d-block text-secondary">to <?= e(ro_date($r['return_datetime'])) ?></small></td><td><strong><?= ro_money($r['estimated_amount']) ?></strong></td><td><form method="post" class="m-0"><?= csrf_field() ?><input type="hidden" name="reservation_id" value="<?= (int)$r['reservation_id'] ?>"><button class="btn ro-btn-primary" type="submit"><i class="bi bi-file-earmark-plus me-1"></i> Create agreement</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<section class="ro-panel"><div class="ro-panel-head"><div><span class="ro-kicker">AGREEMENT REGISTER</span><h2>All agreements</h2></div></div><?php if (!$agreements): ?><div class="ro-empty compact"><div class="ro-empty-icon"><i class="bi bi-files"></i></div><strong>No agreements have been created</strong><p>Use a confirmed reservation above to get started.</p></div><?php else: ?><div class="table-responsive"><table class="table ro-table align-middle"><thead><tr><th>Agreement</th><th>Customer / vehicle</th><th>Daily rate</th><th>Deposit</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody><?php foreach ($agreements as $a): ?><tr><td><strong><?= e($a['agreement_number']) ?></strong><small class="d-block text-secondary"><?= e($a['reservation_code']) ?></small></td><td><?= e($a['first_name'].' '.$a['last_name']) ?><small class="d-block text-secondary"><?= e($a['make'].' '.$a['model'].' · '.$a['registration_no']) ?></small></td><td><?= ro_money($a['agreed_daily_rate']) ?></td><td><?= ro_money($a['security_deposit']) ?></td><td><?= ro_status_badge($a['status']) ?></td><td><?= e(ro_date($a['created_at'])) ?></td><td><a class="btn btn-sm ro-btn-outline" href="<?= e(base_url('admin/agreement-view.php?id='.(int)$a['agreement_id'])) ?>">Review <i class="bi bi-arrow-up-right"></i></a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></div>
<?php require BASE_PATH . '/includes/footer.php'; ?>
